solution.solution.cpp:
#include <concepts>
#include <string>

template <std::integral T>
std::string kind(const T&)
{
    return "integer";
}

template <std::floating_point T>
std::string kind(const T&)
{
    return "decimal";
}

template <typename T>
std::string kind(const T&)
{
    return "something else";
}

template <typename T>
concept Shape = requires(const T& shape)
{
    { shape.area() } -> std::convertible_to<double>;
    { shape.name() } -> std::convertible_to<std::string>;
};

std::string describe(const Shape auto& shape)
{
    return std::string{ shape.name() } + " with area " + std::to_string(static_cast<double>(shape.area()));
}

unitTests:
struct Square { double side{ 2 }; double area() const { return side * side; } std::string name() const { return "square"; } };
struct Dot { int area() const { return 0; } const char* name() const { return "dot"; } };
struct NoName { double area() const { return 1; } };
template <typename T> concept Describable = requires(const T& t) { describe(t); };

static_assert(Shape<Square> && Shape<Dot>);
static_assert(!Shape<NoName> && !Shape<int>);
static_assert(Describable<Square> && !Describable<NoName> && !Describable<double>);

TEST("kind") { CHECK_EQ(kind(5), "integer"); CHECK_EQ(kind('x'), "integer"); CHECK_EQ(kind(2.5), "decimal"); CHECK_EQ(kind(1.0f), "decimal"); CHECK_EQ(kind(std::string{ "hi" }), "something else"); CHECK_EQ(kind(Square{}), "something else"); }
TEST("describe") { CHECK_EQ(describe(Square{}), "square with area 4.000000"); CHECK_EQ(describe(Dot{}), "dot with area 0.000000"); }

